// Game engine initialization and UI management
const game = new GameState();

function renderScene(sceneId) {
    const scene = story[sceneId];
    if (!scene) {
        console.error(`Scene not found: ${sceneId}`);
        return;
    }

    // Update current scene
    game.currentScene = sceneId;

    // Render narrative
    const narrativeDiv = document.getElementById('narrative');
    narrativeDiv.className = 'narrative-text';
    narrativeDiv.innerHTML = `<h3>${scene.title}</h3>${scene.content}`;

    // Render choices
    const choicesDiv = document.getElementById('choices');
    choicesDiv.innerHTML = '';

    scene.choices.forEach((choice, index) => {
        // Check requirements
        let disabled = false;
        if (choice.requirements) {
            if (choice.requirements.specialization && game.specialization !== choice.requirements.specialization) {
                disabled = true;
            }
        }

        const button = document.createElement('button');
        button.className = 'choice-button';
        button.textContent = choice.text;
        button.disabled = disabled;

        button.onclick = () => {
            // Apply effects
            if (choice.effects) {
                if (choice.effects.stats) {
                    Object.entries(choice.effects.stats).forEach(([stat, amount]) => {
                        game.updateStat(stat, amount);
                    });
                }
                if (choice.effects.relationships) {
                    Object.entries(choice.effects.relationships).forEach(([agent, amount]) => {
                        game.updateRelationship(agent, amount);
                    });
                }
            }

            // Record choice
            game.recordChoice(sceneId, index);

            // Set specialization if specified
            if (choice.specialization) {
                game.specialization = choice.specialization;
            }

            // Render next scene
            renderScene(choice.target);
        };

        choicesDiv.appendChild(button);
    });

    // Render stats
    renderStats();

    // Update save info
    updateSaveInfo();
}

function renderStats() {
    const statsDiv = document.getElementById('stats');
    statsDiv.innerHTML = '';

    // Stats
    Object.entries(game.stats).forEach(([stat, value]) => {
        const statDiv = document.createElement('div');
        statDiv.className = 'stat-item';
        statDiv.innerHTML = `
            <div class="stat-value">${value}</div>
            <div class="stat-label">${stat.charAt(0).toUpperCase() + stat.slice(1)}</div>
        `;
        statsDiv.appendChild(statDiv);
    });

    // Specialization if set
    if (game.specialization) {
        const specDiv = document.createElement('div');
        specDiv.className = 'stat-item';
        specDiv.innerHTML = `
            <div class="stat-value" style="color: #4299e1;">${game.specialization.charAt(0).toUpperCase() + game.specialization.slice(1)}</div>
            <div class="stat-label">Specialization</div>
        `;
        statsDiv.appendChild(specDiv);
    }
}
