    if (choice.specialization && !gameState.specialization) {
        gameState.specialization = choice.specialization;
        currentSpecialization = choice.specialization.charAt(0).toUpperCase() + choice.specialization.slice(1) + ' Model';
    }

    // Move to next scene
    gameState.currentScene = choice.target;
    updateUI();
}

function saveGame() {
    gameState.save();
}

function loadGame() {
    if (gameState.load()) {
        currentSpecialization = gameState.specialization ? 
            gameState.specialization.charAt(0).toUpperCase() + gameState.specialization.slice(1) + ' Model' : null;
        updateUI();
    } else {
        alert('No saved game found!');
    }
}

function resetGame() {
    if (confirm('Are you sure you want to restart? All progress will be lost.')) {
        gameState.reset();
        currentSpecialization = null;
        updateUI();
    }
}

// Initialize game
document.addEventListener('DOMContentLoaded', () => {
    // Try to load saved game first
    if (!gameState.load()) {
        // Start new game
        gameState.reset();
    } else {
        currentSpecialization = gameState.specialization ? 
            gameState.specialization.charAt(0).toUpperCase() + gameState.specialization.slice(1) + ' Model' : null;
    }
    updateUI();
});
